1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Bulwark</title>
7	<style>
8	  :root {
9	    --bg: #f6f7f9; --surface: #ffffff; --border: #e3e6eb; --text: #14171c; --muted: #5d6673;
10	    --accent: #2f5bea; --accent-ink: #fff; --pass: #1f9d55; --broken: #d97706; --crash: #dc2626; --hung: #7c3aed; --runaway: #db2777;
11	    --pending: #d5d9e0; --shadow: 0 1px 2px rgba(16,24,40,.06); --code-bg: #f1f3f6;
12	    --red-agent: #dc2626; --blue-agent: #2f5bea; --judge-agent: #b45309; --guard: #0f766e;
13	  }
14	  @media (prefers-color-scheme: dark) {
15	    :root:not([data-theme="light"]) {
16	      --bg: #0d1015; --surface: #151a21; --border: #262d38; --text: #e8ebf0; --muted: #929cab;
17	      --accent: #6b8cff; --accent-ink: #0d1015; --pass: #34c27a; --broken: #f59e0b; --crash: #f05252; --hung: #a78bfa; --runaway: #f472b6;
18	      --pending: #2c3440; --shadow: none; --code-bg: #0f1319;
19	      --red-agent: #f87171; --blue-agent: #7d9bff; --judge-agent: #fbbf24; --guard: #2dd4bf;
20	    }
21	  }
22	  * { box-sizing: border-box; }
23	  body { margin: 0; background: var(--bg); color: var(--text); font: 14px/1.5 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif; }
24	  .wrap { max-width: 1240px; margin: 0 auto; padding: 24px 16px 60px; }
25	  header { display: flex; flex-wrap: wrap; gap: 16px; align-items: flex-end; justify-content: space-between; margin-bottom: 18px; }
26	  h1 { margin: 0; font-size: 26px; letter-spacing: -.02em; }
27	  h1 a { color: inherit; text-decoration: none; }
28	  h1 span { color: var(--accent); }
29	  .sub { color: var(--muted); margin: 4px 0 0; }
30	  .controls { display: flex; gap: 10px; align-items: flex-end; flex-wrap: wrap; }
31	  label { display: flex; flex-direction: column; font-size: 12px; color: var(--muted); gap: 4px; }
32	  label.check { flex-direction: row; align-items: center; gap: 6px; padding-bottom: 8px; color: var(--text); font-size: 13px; }
33	  input[type=number] { width: 76px; padding: 7px 9px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface); color: var(--text); font: inherit; }
34	  button { padding: 8px 16px; border: 0; border-radius: 8px; background: var(--accent); color: var(--accent-ink); font: inherit; font-weight: 650; cursor: pointer; }
35	  button.ghost { background: var(--surface); color: var(--text); border: 1px solid var(--border); }
36	  button:disabled { opacity: .55; cursor: progress; }
37	  .panel { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; box-shadow: var(--shadow); padding: 16px 18px; }
38	  h2 { margin: 0 0 10px; font-size: 12px; text-transform: uppercase; letter-spacing: .07em; color: var(--muted); }
39	  .top { display: grid; grid-template-columns: 1.2fr 1fr; gap: 14px; margin-bottom: 14px; }
40	  ol.rules { margin: 0; padding-left: 20px; }
41	  .stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
42	  .stat b { display: block; font-size: 26px; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
43	  .stat small { color: var(--muted); }
44	  .badge { font-size: 11px; padding: 2px 8px; border-radius: 99px; border: 1px solid var(--border); color: var(--muted); white-space: nowrap; }
45	
46	  /* loop */
47	  #loop { display: none; margin-bottom: 14px; }
48	  .stepper { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 12px; }
49	  .stepper span { padding: 5px 12px; border-radius: 99px; border: 1px solid var(--border); color: var(--muted); font-size: 12px; font-weight: 600; }
50	  .stepper span.active { border-color: var(--accent); color: var(--accent); }
51	  .stepper span.done { background: color-mix(in srgb, var(--pass) 14%, transparent); border-color: transparent; color: var(--pass); }
52	  .loopgrid { display: grid; grid-template-columns: 1.5fr 1fr; gap: 14px; }
53	  #timeline { max-height: 560px; overflow-y: auto; font-size: 13px; }
54	  .ev { padding: 6px 0; border-top: 1px dashed var(--border); }
55	  .ev:first-child { border-top: 0; }
56	  .ev.faulthead { font-weight: 700; padding-top: 12px; font-size: 14px; }
57	  .ev .dim { color: var(--muted); }
58	  .tag { display: inline-block; font: 700 11px ui-monospace, monospace; padding: 1px 6px; border-radius: 4px; margin-right: 6px; color: #fff; vertical-align: 1px; }
59	  .tag.red { background: var(--red-agent); } .tag.blue { background: var(--blue-agent); } .tag.judge { background: var(--judge-agent); } .tag.guard { background: var(--guard); }
60	  .ok { color: var(--pass); font-weight: 700; } .bad { color: var(--crash); font-weight: 700; } .warn { color: var(--broken); font-weight: 700; }
61	  .chip { font: 12px ui-monospace, monospace; color: var(--muted); }
62	  details { margin-top: 4px; }
63	  summary { cursor: pointer; color: var(--accent); font-size: 12px; }
64	  pre.diff { background: var(--code-bg); border-radius: 8px; padding: 10px 12px; overflow-x: auto; font: 12px/1.55 ui-monospace, SFMono-Regular, Menlo, monospace; margin: 6px 0 0; }
65	  pre.diff .add { color: var(--pass); } pre.diff .del { color: var(--crash); } pre.diff .hunk { color: var(--accent); }
66	  ul.findings { margin: 0; padding: 0; list-style: none; font-size: 13px; }
67	  ul.findings li { padding: 5px 0; border-top: 1px dashed var(--border); }
68	  ul.findings code { font-size: 12px; color: var(--muted); }
69	  .sev { font: 700 10px ui-monospace, monospace; text-transform: uppercase; margin-right: 6px; }
70	  .sev.high { color: var(--crash); } .sev.medium { color: var(--broken); }
71	  #results { margin-top: 14px; display: none; }
72	  .bigscore { font-size: 30px; font-weight: 800; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
73	  .links { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
74	  .links a { font-size: 12px; padding: 4px 10px; border: 1px solid var(--border); border-radius: 99px; color: var(--text); text-decoration: none; }
75	  .links a:hover { border-color: var(--accent); color: var(--accent); }
76	
77	  /* cards */
78	  .legend { display: flex; flex-wrap: wrap; gap: 14px; margin: 4px 0 12px; color: var(--muted); font-size: 12px; }
79	  .legend i { display: inline-block; width: 10px; height: 10px; border-radius: 3px; margin-right: 6px; vertical-align: -1px; }
80	  .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(330px, 1fr)); gap: 14px; }
81	  .card .head { display: flex; justify-content: space-between; gap: 10px; align-items: baseline; }
82	  .card code { font-size: 12px; color: var(--accent); }
83	  .score { font-size: 20px; font-weight: 750; font-variant-numeric: tabular-nums; white-space: nowrap; }
84	  .title { font-weight: 600; margin: 2px 0; }
85	  .hyp { color: var(--muted); font-size: 13px; margin: 0 0 10px; min-height: 40px; }
86	  .row { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
87	  .row .lbl { width: 44px; font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .05em; flex: none; }
88	  .dots { display: flex; flex-wrap: wrap; gap: 3px; }
89	  .dot { width: 12px; height: 12px; border-radius: 3px; background: var(--pending); transition: background .2s; }
90	  .dot.pass { background: var(--pass); } .dot.broken { background: var(--broken); } .dot.crashed { background: var(--crash); }
91	  .dot.hung { background: var(--hung); } .dot.runaway { background: var(--runaway); }
92	  .after-row { display: none; }
93	  .cardstatus { font-size: 12px; margin-top: 6px; min-height: 18px; }
94	  .ci { position: relative; height: 8px; background: var(--pending); border-radius: 4px; margin: 8px 0 2px; }
95	  .ci .band { position: absolute; top: 0; bottom: 0; background: color-mix(in srgb, var(--accent) 35%, transparent); border-radius: 4px; }
96	  .ci .pt { position: absolute; top: -3px; width: 3px; height: 14px; background: var(--accent); border-radius: 2px; display: none; }
97	  .cilabel { font-size: 12px; color: var(--muted); }
98	  ul.broken { margin: 8px 0 0; padding: 0; list-style: none; font-size: 13px; }
99	  ul.broken li { padding: 3px 0; border-top: 1px dashed var(--border); }
100	  ul.broken li b { color: var(--crash); }
101	  .dot[data-seed] { cursor: pointer; }
102	  .dot[data-seed]:hover, .dot[data-seed]:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
103	
104	  /* trial replay */
105	  .modal { position: fixed; inset: 0; z-index: 50; display: flex; align-items: center; justify-content: center; padding: 16px; background: color-mix(in srgb, #000 45%, transparent); }
106	  .modal[hidden] { display: none; }
107	  .modal-box { width: min(880px, 100%); max-height: calc(100vh - 32px); display: flex; flex-direction: column; gap: 10px; padding: 16px 18px; }
108	  .rp-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; }
109	  .rp-head h3 { margin: 0; font-size: 17px; letter-spacing: -.01em; word-break: break-word; }
110	  .rp-head h3 code { color: var(--accent); }
111	  .rp-close { padding: 4px 10px; flex: none; }
112	  .rp-meta { display: flex; flex-wrap: wrap; gap: 6px; font-size: 12px; }
113	  .rp-meta .badge { color: var(--text); }
114	  .rp-out { font-weight: 700; }
115	  .rp-out.completed { color: var(--pass); } .rp-out.crashed { color: var(--crash); } .rp-out.hung { color: var(--hung); } .rp-out.runaway { color: var(--runaway); }
116	  ul.rp-broken { margin: 0; padding: 0; list-style: none; font-size: 13px; max-height: 30vh; overflow-y: auto; }
117	  ul.rp-broken li { padding: 4px 0; border-top: 1px dashed var(--border); }
118	  ul.rp-broken li:first-child { border-top: 0; }
119	  ul.rp-broken b { color: var(--crash); }
120	  ul.rp-broken small { display: block; color: var(--muted); }
121	  .rp-nav { display: flex; align-items: center; gap: 8px; flex: none; }
122	  .rp-head, .rp-meta, ul.rp-broken { flex: none; }
123	  .rp-nav button { padding: 5px 12px; }
124	  .rp-nav .counter { font: 12px ui-monospace, monospace; color: var(--muted); flex: 1; text-align: center; }
125	  ol.rp-steps { list-style: none; margin: 0; padding: 0; overflow-y: auto; min-height: 120px; flex: 1; border: 1px solid var(--border); border-radius: 8px; }
126	  .rp-step { display: grid; grid-template-columns: 92px 1fr; gap: 2px 10px; padding: 7px 10px; border-top: 1px solid var(--border); border-left: 3px solid transparent; cursor: pointer; font-size: 13px; }
127	  .rp-step:first-child { border-top: 0; }
128	  .rp-step:hover { background: color-mix(in srgb, var(--accent) 5%, transparent); }
129	  .rp-step.rp-bad { border-left-color: var(--crash); background: color-mix(in srgb, var(--crash) 9%, transparent); }
130	  .rp-step.rp-warn { border-left-color: var(--broken); background: color-mix(in srgb, var(--broken) 9%, transparent); }
131	  .rp-step.current { background: color-mix(in srgb, var(--accent) 12%, transparent); box-shadow: inset 0 0 0 2px var(--accent); }
132	  .rp-step .when { font: 11px ui-monospace, monospace; color: var(--muted); }
133	  .rp-step .what { min-width: 0; word-break: break-word; }
134	  .rp-step pre { grid-column: 2; margin: 3px 0 0; padding: 5px 8px; background: var(--code-bg); border-radius: 6px; font: 11.5px/1.5 ui-monospace, SFMono-Regular, Menlo, monospace; white-space: pre-wrap; word-break: break-all; max-height: 3.2em; overflow: hidden; }
135	  .rp-step.current pre { max-height: 260px; overflow-y: auto; }
136	  .rp-step pre .k { color: var(--muted); }
137	  .rtype { display: inline-block; font: 700 10px ui-monospace, monospace; text-transform: uppercase; padding: 1px 6px; border-radius: 4px; color: #fff; margin-bottom: 2px; }
138	  .rtype.brain { background: var(--blue-agent); } .rtype.tool { background: var(--muted); } .rtype.fault { background: var(--crash); }
139	  .rtype.timeout { background: var(--broken); } .rtype.effect { background: var(--guard); } .rtype.outcome { background: var(--text); color: var(--bg); }
140	  .rp-hint { font-size: 11px; color: var(--muted); }
141	  @media (max-width: 560px) {
142	    .modal { padding: 0; }
143	    .modal-box { width: 100%; max-height: 100vh; height: 100vh; height: 100dvh; border-radius: 0; padding: 14px 16px; }
144	    .rp-step { grid-template-columns: 1fr; }
145	    .rp-step pre { grid-column: 1; }
146	    .modal .rp-hint { display: none; }
147	  }
148	  @media (max-width: 900px) { .top, .loopgrid { grid-template-columns: 1fr; } }
149	  @media (max-width: 560px) { .grid { grid-template-columns: 1fr; } .stats { grid-template-columns: 1fr 1fr; } }
150	</style>
151	</head>
152	<body>
153	<div class="wrap">
154	  <header>
155	    <div>
156	      <h1><a href="/">Bulwark</a> <span>/</span> <span id="target">…</span></h1>
157	      <p class="sub">Attack in a sandbox, fix what breaks, prove it with statistics.
158	        <span class="badge" id="nl">neatlogs</span> <span class="badge" id="fx">fixer</span></p>
159	    </div>
160	    <div class="controls">
161	      <label>Trials / fault <input id="trials" type="number" min="5" max="100" value="20"></label>
162	      <label>Seed <input id="seed" type="number" value="42"></label>
163	      <label class="check" title="Use past runs to try the best-known fix first"><input id="memory" type="checkbox"> Remember past fixes</label>
164	      <button class="ghost" id="run">Attack only</button>
165	      <button id="loopbtn">Attack → Fix → Prove</button>
166	    </div>
167	  </header>
168	
169	  <div class="top">
170	    <div class="panel"><h2>Business rules (plain English)</h2><ol class="rules" id="rules"></ol></div>
171	    <div class="panel">
172	      <h2 id="statsTitle">This run</h2>
173	      <div class="stats" id="stats">
174	        <div class="stat"><b id="s1">–</b><small id="s1l">trials run</small></div>
175	        <div class="stat"><b id="s2">–</b><small id="s2l">failed trials</small></div>
176	        <div class="stat"><b id="s3">–</b><small id="s3l">refunded beyond order totals</small></div>
177	      </div>
178	    </div>
179	  </div>
180	
181	  <section id="loop">
182	    <div class="stepper" id="stepper">
183	      <span data-step="analyze">1 · Red analyzes code</span>
184	      <span data-step="attack">2 · Red attacks</span>
185	      <span data-step="fix">3 · Blue fixes, Judge verifies</span>
186	      <span data-step="reattack">4 · Re-attack</span>
187	      <span data-step="report">5 · Report</span>
188	    </div>
189	    <div class="loopgrid">
190	      <div class="panel"><h2>Timeline</h2><div id="timeline"></div></div>
191	      <div>
192	        <div class="panel"><h2>Weak links found in the code</h2><ul class="findings" id="findings"><li class="dim">Waiting for Red…</li></ul></div>
193	        <div class="panel" id="results">
194	          <h2>Result</h2>
195	          <div class="bigscore" id="bigscore"></div>
196	          <div class="dim" id="resultline" style="color:var(--muted)"></div>
197	          <div id="residual" style="margin-top:10px;font-size:13px"></div>
198	          <div style="margin-top:10px"><img id="badge" alt="resilience badge" height="20"></div>
199	          <div class="links" id="links"></div>
200	        </div>
201	      </div>
202	    </div>
203	  </section>
204	
205	  <div class="legend">
206	    <span><i style="background:var(--pass)"></i>passed every rule</span>
207	    <span><i style="background:var(--broken)"></i>finished but broke a rule</span>
208	    <span><i style="background:var(--crash)"></i>crashed</span>
209	    <span><i style="background:var(--hung)"></i>hung</span>
210	    <span><i style="background:var(--runaway)"></i>runaway loop</span>
211	  </div>
212	  <div class="grid" id="grid"></div>
213	  <p class="rp-hint" style="margin-top:10px">Click any trial square to replay it step by step from its seed.</p>
214	</div>
215	
216	<div class="modal" id="replay" hidden role="dialog" aria-modal="true" aria-labelledby="rpTitle">
217	  <div class="panel modal-box">
218	    <div class="rp-head">
219	      <h3 id="rpTitle">Trial replay</h3>
220	      <button class="ghost rp-close" id="rpClose" aria-label="Close replay">✕</button>
221	    </div>
222	    <div class="rp-meta" id="rpMeta"></div>
223	    <ul class="rp-broken" id="rpBroken"></ul>
224	    <div class="rp-nav">
225	      <button class="ghost" id="rpPrev">← Prev</button>
226	      <span class="counter" id="rpCounter"></span>
227	      <button class="ghost" id="rpNext">Next →</button>
228	    </div>
229	    <ol class="rp-steps" id="rpSteps"></ol>
230	    <div class="rp-hint">← → to step · Esc to close · timings are wall-clock; the events replay identically from the seed</div>
231	  </div>
232	</div>
233	
234	<script>
235	const $ = (id) => document.getElementById(id);
236	const pct = (x) => Math.round(x * 100) + '%';
237	const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
238	const ORDER_TOTAL = 49;
239	let meta, totals, busy = false;
240	
241	function card(f) {
242	  const el = document.createElement('div');
243	  el.className = 'panel card';
244	  el.id = 'card-' + f.id;
245	  el.innerHTML = `
246	    <div class="head"><code>${f.id}</code><span class="score">–</span></div>
247	    <div class="title">${esc(f.title)}</div>
248	    <p class="hyp">${esc(f.hypothesis)}</p>
249	    <div class="row"><span class="lbl">before</span><div class="dots before"></div></div>
250	    <div class="row after-row"><span class="lbl">after</span><div class="dots after"></div></div>
251	    <div class="ci"><div class="band" style="left:0;width:0"></div><div class="pt"></div></div>
252	    <div class="cilabel">95% confidence interval for pass rate</div>
253	    <div class="cardstatus"></div>
254	    <div class="result"></div>`;
255	  return el;
256	}
257	
258	function resetCards() { $('grid').replaceChildren(...meta.faults.map(card)); }
259	
260	async function load() {
261	  meta = await (await fetch('/api/meta')).json();
262	  $('target').textContent = meta.target;
263	  $('nl').textContent = meta.neatlogs ? 'neatlogs: exporting traces' : 'neatlogs: local only';
264	  $('fx').textContent = 'fixer: ' + meta.fixer;
265	  $('rules').innerHTML = meta.rules.map((r) => `<li>${esc(r)}</li>`).join('');
266	  resetCards();
267	}
268	
269	function setBusy(on) {
270	  busy = on;
271	  $('run').disabled = $('loopbtn').disabled = on;
272	  $('loopbtn').textContent = on ? 'Working…' : 'Attack → Fix → Prove';
273	}
274	
275	function setStats(vals, labels) {
276	  ['s1', 's2', 's3'].forEach((id, i) => { $(id).textContent = vals[i]; if (labels) $(id + 'l').textContent = labels[i]; });
277	}
278	
279	const dotClass = (t) => (t.passed ? 'pass' : t.outcome === 'completed' ? 'broken' : t.outcome);
280	
281	// Squares in trial order, each carrying its seed (and, for patched code, the loop workspace) so it can be replayed.
282	function dotsFromResult(r, src = {}) {
283	  if (r.perTrial) {
284	    const extra = (src.run ? ` data-run="${esc(src.run)}"` : '') + (src.ws ? ` data-ws="${esc(src.ws)}"` : '');
285	    return r.perTrial.map((t) =>
286	      `<span class="dot ${dotClass(t)}" role="button" tabindex="0" data-fault="${esc(r.fault)}" data-seed="${t.seed}"${extra} title="seed ${t.seed} · ${esc(t.outcome)}${t.passed ? '' : ' · broke a rule'}${src.ws ? ' · patched code' : ''} · click to replay"></span>`).join('');
287	  }
288	  const failedCompleted = r.outcomes.completed - r.passed;
289	  return [
290	    ...Array(r.passed).fill('pass'), ...Array(Math.max(0, failedCompleted)).fill('broken'),
291	    ...Array(r.outcomes.crashed).fill('crashed'), ...Array(r.outcomes.hung).fill('hung'), ...Array(r.outcomes.runaway).fill('runaway'),
292	  ].map((k) => `<span class="dot ${k}"></span>`).join('');
293	}
294	
295	function showResult(el, r) {
296	  el.querySelector('.band').style.cssText = `left:${r.ci95[0] * 100}%;width:${(r.ci95[1] - r.ci95[0]) * 100}%`;
297	  el.querySelector('.pt').style.cssText = `display:block;left:calc(${r.passRate * 100}% - 1.5px)`;
298	  el.querySelector('.cilabel').textContent = `95% CI for pass rate: ${pct(r.ci95[0])}–${pct(r.ci95[1])} · p95 ${Math.round(r.p95Ms)}ms`;
299	  const broken = Object.entries(r.violations).filter(([, n]) => n > 0);
300	  el.querySelector('.result').innerHTML = broken.length
301	    ? `<ul class="broken">${broken.map(([rule, n]) => `<li><b>${n}×</b> ${esc(rule)}</li>`).join('')}</ul>`
302	    : '<div class="ok" style="font-size:13px;margin-top:8px">✓ All rules held</div>';
303	}
304	
305	/* ---------- Attack only ---------- */
306	function runChaos() {
307	  if (busy) return;
308	  const trials = Number($('trials').value) || 20, seed = Number($('seed').value) || 42;
309	  resetCards();
310	  $('loop').style.display = 'none';
311	  $('statsTitle').textContent = 'This run';
312	  totals = { trials: 0, fail: 0, money: 0 };
313	  setStats([0, 0, '$0'], ['trials run', 'failed trials', 'refunded beyond order totals']);
314	  setBusy(true);
315	  const es = new EventSource(`/api/run?trials=${trials}&seed=${seed}`);
316	  es.addEventListener('experiment-start', (e) => {
317	    const { fault, trials } = JSON.parse(e.data);
318	    $('card-' + fault).querySelector('.dots.before').innerHTML = '<span class="dot"></span>'.repeat(trials);
319	  });
320	  es.addEventListener('trial', (e) => {
321	    const t = JSON.parse(e.data);
322	    const dot = $('card-' + t.fault).querySelectorAll('.dots.before .dot')[t.index];
323	    dot.className = 'dot ' + dotClass(t);
324	    Object.assign(dot.dataset, { fault: t.fault, seed: t.seed });
325	    dot.setAttribute('role', 'button');
326	    dot.tabIndex = 0;
327	    dot.title = `click to replay · seed ${t.seed} · ${t.outcome} · ${t.steps} steps · ${t.durationMs}ms` +
328	      (t.refunds.length ? ` · refunds: $${t.refunds.join(', $')}` : '') +
329	      (t.broken.length ? '\n✗ ' + t.broken.map((b) => b.rule + (b.detail ? ` (${b.detail})` : '')).join('\n✗ ') : '') +
330	      (t.error ? `\nerror: ${t.error}` : '');
331	    totals.trials++;
332	    if (!t.passed) totals.fail++;
333	    totals.money += Math.max(0, t.refunds.reduce((s, a) => s + a, 0) - ORDER_TOTAL);
334	    setStats([totals.trials, totals.fail, '$' + totals.money.toLocaleString()]);
335	  });
336	  es.addEventListener('experiment-done', (e) => {
337	    const r = JSON.parse(e.data), el = $('card-' + r.fault);
338	    el.querySelector('.score').textContent = `${r.passed}/${r.trials}`;
339	    el.querySelector('.score').style.color = r.passed === r.trials ? 'var(--pass)' : 'var(--crash)';
340	    showResult(el, r);
341	  });
342	  const finish = () => { es.close(); setBusy(false); };
343	  es.addEventListener('done', finish);
344	  es.addEventListener('error', finish);
345	}
346	
347	/* ---------- Attack → Fix → Prove ---------- */
348	let attempts = 0, rollbacks = 0, runId = '';
349	
350	function step(name) {
351	  const order = ['analyze', 'attack', 'fix', 'reattack', 'report'];
352	  const i = order.indexOf(name);
353	  document.querySelectorAll('#stepper span').forEach((s) => {
354	    const j = order.indexOf(s.dataset.step);
355	    s.className = j < i ? 'done' : j === i ? 'active' : '';
356	  });
357	}
358	
359	function tl(html, cls = '') {
360	  const div = document.createElement('div');
361	  div.className = 'ev ' + cls;
362	  div.innerHTML = html;
363	  $('timeline').appendChild(div);
364	  $('timeline').scrollTop = $('timeline').scrollHeight;
365	}
366	
367	function renderDiff(diff) {
368	  return diff.split('\n').map((l) => {
369	    const cls = l.startsWith('+') && !l.startsWith('+++') ? 'add' : l.startsWith('-') && !l.startsWith('---') ? 'del' : l.startsWith('@@') ? 'hunk' : '';
370	    return cls ? `<span class="${cls}">${esc(l)}</span>` : esc(l);
371	  }).join('\n');
372	}
373	
374	function cardStatus(fault, html) { const el = $('card-' + fault); if (el) el.querySelector('.cardstatus').innerHTML = html; }
375	
376	const handlers = {
377	  'run-start': (e) => {
378	    runId = e.runId;
379	    step('analyze');
380	    tl(`<span class="dim">Run ${esc(e.runId)} · fixer <b>${esc(e.fixer)}</b> · Red ${e.redTrials} trials/fault · Judge ${e.judgeTrials} trials/fault on its own seeds</span>`);
381	  },
382	  analyze: (e) => {
383	    tl(`<span class="tag red">RED</span>found <b>${e.findings.length}</b> weak links in the code`);
384	    $('findings').innerHTML = e.findings.map((f) =>
385	      `<li><span class="sev ${f.severity}">${f.severity}</span>${esc(f.why)}<br><code>${esc(f.file)}:${f.line} → ${f.faults.join(', ')}</code></li>`).join('');
386	    step('attack');
387	  },
388	  scorecard: (e) => {
389	    const after = e.phase === 'after';
390	    for (const r of e.results) {
391	      const el = $('card-' + r.fault);
392	      if (!el) continue;
393	      el.querySelector(after ? '.dots.after' : '.dots.before').innerHTML = dotsFromResult(r, after && e.ws ? { run: runId, ws: e.ws } : {});
394	      if (after) {
395	        el.querySelector('.after-row').style.display = 'flex';
396	        const before = el.dataset.before;
397	        el.querySelector('.score').innerHTML = `<span style="color:var(--muted);font-weight:500">${before} →</span> <span style="color:${r.passed === r.trials ? 'var(--pass)' : 'var(--crash)'}">${r.passed}/${r.trials}</span>`;
398	        showResult(el, r);
399	      } else {
400	        el.dataset.before = `${r.passed}/${r.trials}`;
401	        el.querySelector('.score').textContent = el.dataset.before;
402	        el.querySelector('.score').style.color = r.passed === r.trials ? 'var(--pass)' : 'var(--crash)';
403	        showResult(el, r);
404	      }
405	    }
406	    if (after) {
407	      tl(`<span class="tag red">RED</span>re-attacked the final code with the original seeds: <b class="${e.overall === 1 ? 'ok' : 'warn'}">${pct(e.overall)}</b> of trials kept every rule`);
408	      step('report');
409	    } else {
410	      tl(`<span class="tag red">RED</span>attack scorecard: <b class="bad">${pct(e.overall)}</b> of trials kept every rule`);
411	      setStats([pct(e.overall), 0, 0], ['resilience before', 'fix attempts', 'rollbacks']);
412	      step('fix');
413	    }
414	  },
415	  log: (e) => tl(`<span class="dim">${esc(e.message)}</span>`),
416	  'fault-start': (e) => { tl(`▶ ${esc(e.fault)} <span class="dim" style="font-weight:400">${esc(e.hypothesis)}</span>`, 'faulthead'); cardStatus(e.fault, '<span class="warn">fixing…</span>'); },
417	  'fault-skip': (e) => { tl(`<span class="dim">skipped: ${esc(e.reason)}</span>`); cardStatus(e.fault, `<span class="ok">✓ ${esc(e.reason)}</span>`); },
418	  checkpoint: (e) => {
419	    if (e.action === 'restore') { rollbacks++; setStats([$('s1').textContent, attempts, rollbacks]); }
420	    tl(e.action === 'save' ? `<span class="chip">⎘ checkpoint ${esc(e.id)}</span>` : `<span class="chip bad">↺ rolled back to ${esc(e.id)}</span>`);
421	  },
422	  attempt: (e) => {
423	    attempts++;
424	    setStats([$('s1').textContent, attempts, rollbacks]);
425	    tl(`<span class="tag blue">BLUE</span>attempt ${e.n}: <b>${esc(e.title)}</b> <span class="dim">(${esc(e.strategy)} · ${esc(e.author)} · +${e.added} −${e.removed})</span>
426	        <details><summary>rationale and diff</summary><div class="dim" style="margin-top:4px">${esc(e.rationale)}</div><pre class="diff">${renderDiff(e.diff)}</pre></details>`);
427	    tl(`<span class="tag judge">JUDGE</span><span class="dim">re-running all attacks on fresh seeds…</span>`, 'pending-judge');
428	  },
429	  verdict: (e) => {
430	    document.querySelectorAll('.pending-judge').forEach((n) => n.remove());
431	    const cls = e.status === 'fixed' ? 'ok' : e.status === 'inconclusive' ? 'warn' : 'bad';
432	    tl(`<span class="tag judge">JUDGE</span><span class="${cls}">${e.status.toUpperCase()}</span> ${esc(e.reasons.join('; '))}`);
433	  },
434	  mutation: (e) => tl(`<span class="tag guard">GUARD</span>regression test: without the fix ${e.unfixedPassed}/${e.trials}, with it ${e.fixedPassed}/${e.trials} ${e.ok ? '<span class="ok">✓ proven to guard the fix</span>' : '<span class="bad">✗ not proven</span>'}`),
435	  'fault-done': (e) => {
436	    if (e.status === 'fixed') cardStatus(e.fault, `<span class="ok">✓ fixed and verified</span> <span class="dim">(${e.attempts} attempt${e.attempts > 1 ? 's' : ''})</span>`);
437	    else if (e.status === 'unfixed') cardStatus(e.fault, '<span class="bad">✗ not fixed</span>');
438	    if (e.status !== 'skipped') step('fix');
439	  },
440	  residual: (e) => {
441	    $('residual').innerHTML = e.findings.length
442	      ? `<b class="warn">Remaining risk:</b> every attack passes, but the analyzer still sees:<ul class="findings">${e.findings.map((f) => `<li>${esc(f.why)} <code>${esc(f.file)}:${f.line}</code></li>`).join('')}</ul>`
443	      : '<span class="ok">No weak links remain in the final code.</span>';
444	    step('reattack');
445	  },
446	  'run-done': (e) => {
447	    const s = e.summary;
448	    step('done');
449	    document.querySelectorAll('#stepper span').forEach((n) => (n.className = 'done'));
450	    $('results').style.display = 'block';
451	    $('bigscore').innerHTML = `<span class="bad">${pct(s.overallBefore)}</span> → <span class="${s.overallAfter === 1 ? 'ok' : 'warn'}">${pct(s.overallAfter)}</span>`;
452	    $('resultline').textContent = `resilience · fixed ${s.fixed.length}, skipped ${s.skipped.length}, unfixed ${s.unfixed.length} · ${s.attempts} attempts, ${s.rollbacks} rollbacks`;
453	    $('badge').src = '/badge.svg?t=' + Date.now();
454	    const art = (file, label) => `<a href="/api/artifact?run=${encodeURIComponent(s.runId)}&file=${encodeURIComponent(file)}" target="_blank">${label}</a>`;
455	    $('links').innerHTML = [art('PR.md', 'PR description'), art('fix.patch', 'fix.patch'), art('scorecard-before.md', 'scorecard before'), art('scorecard-after.md', 'scorecard after'),
456	      ...s.artifacts.postmortems.map((p) => { const f = p.split('/').pop(); return art(f, f.replace('postmortem-', 'postmortem: ').replace('.md', '')); })].join('');
457	    setStats([`${pct(s.overallBefore)} → ${pct(s.overallAfter)}`, s.attempts, s.rollbacks], ['resilience', 'fix attempts', 'rollbacks']);
458	    tl(`<b>Done.</b> Resilience ${pct(s.overallBefore)} → ${pct(s.overallAfter)}. Artifacts in <code>${esc(s.dir)}</code>`);
459	  },
460	};
461	
462	function runLoopUI() {
463	  if (busy) return;
464	  const trials = Number($('trials').value) || 20, seed = Number($('seed').value) || 42, memory = $('memory').checked ? 1 : 0;
465	  resetCards();
466	  attempts = 0; rollbacks = 0;
467	  $('loop').style.display = 'block';
468	  $('results').style.display = 'none';
469	  $('timeline').innerHTML = '';
470	  $('findings').innerHTML = '<li style="color:var(--muted)">Waiting for Red…</li>';
471	  $('statsTitle').textContent = 'Bulwark loop';
472	  setStats(['–', 0, 0], ['resilience before', 'fix attempts', 'rollbacks']);
473	  setBusy(true);
474	  const es = new EventSource(`/api/loop?trials=${trials}&seed=${seed}&memory=${memory}`);
475	  es.addEventListener('loop', (m) => { const e = JSON.parse(m.data); handlers[e.type]?.(e); if (e.type === 'run-done') { es.close(); setBusy(false); } });
476	  es.addEventListener('loop-error', (m) => { tl(`<span class="bad">Error: ${esc(JSON.parse(m.data).message)}</span>`); es.close(); setBusy(false); });
477	  es.addEventListener('error', () => { es.close(); setBusy(false); });
478	}
479	
480	/* ---------- Trial replay ---------- */
481	const rp = { steps: [], cur: 0, opener: null, req: 0 };
482	const OUTCOME_LABEL = { completed: 'completed', crashed: 'crashed', hung: 'hung', runaway: 'runaway loop' };
483	const json = (v) => esc(JSON.stringify(v) ?? 'undefined');
484	const kv = (label, v) => `<span class="k">${label}</span> ${json(v)}`;
485	
486	function stepView(e) {
487	  const kind = { brain: 'brain', call: 'tool', result: 'tool', error: 'tool', timeout: 'timeout', fault: 'fault', effect: 'effect', outcome: 'outcome' }[e.type] ?? 'tool';
488	  const label = kind === 'effect' ? 'side effect' : kind;
489	  let what = '', body = '', cls = '';
490	  switch (e.type) {
491	    case 'brain':
492	      if (e.decision.type === 'tool') { what = `step ${e.step}: decides to call <b>${esc(e.decision.name)}</b>`; body = kv('input', e.decision.input); }
493	      else { what = `step ${e.step}: final reply`; body = kv('reply', e.decision.reply); }
494	      break;
495	    case 'call':
496	      what = `→ <b>${esc(e.endpoint)}</b> <span class="chip">#${e.call}</span>` + (e.retryOf ? ` <span class="warn">RETRY of #${e.retryOf} (attempt ${e.attempt})</span>` : '');
497	      body = kv('input', e.input);
498	      if (e.retryOf) cls = 'rp-warn';
499	      break;
500	    case 'result':
501	      what = `← <b>${esc(e.endpoint)}</b> <span class="chip">#${e.call} · ${e.ms}ms</span>` + (e.late ? ' <span class="warn">late: the agent had already given up</span>' : '');
502	      body = kv('output', e.output);
503	      if (e.late) cls = 'rp-warn';
504	      break;
505	    case 'error':
506	      what = `✗ <b>${esc(e.endpoint)}</b> <span class="chip">#${e.call} · ${e.ms}ms</span> <span class="bad">error</span>` + (e.late ? ' <span class="dim">(after the agent stopped waiting)</span>' : '');
507	      body = kv('error', e.error);
508	      cls = 'rp-bad';
509	      break;
510	    case 'timeout':
511	      what = `<b>${esc(e.endpoint)}</b> <span class="chip">#${e.call}</span> ${esc(e.detail)}`;
512	      cls = 'rp-warn';
513	      break;
514	    case 'fault':
515	      what = `<b>${esc(e.fault)}</b> injected on <b>${esc(e.endpoint)}</b> <span class="chip">#${e.call}</span><br>${esc(e.detail)}`;
516	      cls = 'rp-bad';
517	      break;
518	    case 'effect':
519	      what = e.effect === 'refund' ? `money moved: refund of <b>$${esc(e.data.amount)}</b> on ${esc(e.data.orderId)}` : `email sent to ${esc(e.data.to)}`;
520	      body = kv(esc(e.effect), e.data);
521	      break;
522	    case 'outcome':
523	      what = `run <span class="rp-out ${esc(e.outcome)}">${esc(OUTCOME_LABEL[e.outcome] ?? e.outcome)}</span> after ${e.steps} steps, ${e.durationMs}ms`;
524	      body = e.error ? kv('error', e.error) : e.reply !== undefined ? kv('reply', e.reply) : '';
525	      if (e.outcome !== 'completed') cls = 'rp-bad';
526	      break;
527	    default:
528	      what = esc(e.type);
529	      body = json(e);
530	  }
531	  return `<li class="rp-step ${cls}" data-i="${e.i}"><div><span class="rtype ${kind}">${label}</span><div class="when">+${Number(e.t)}ms</div></div>` +
532	    `<div class="what">${what}</div>${body ? `<pre>${body}</pre>` : ''}</li>`;
533	}
534	
535	function rpGo(i) {
536	  if (!rp.steps.length) return;
537	  rp.cur = Math.max(0, Math.min(rp.steps.length - 1, i));
538	  const lis = $('rpSteps').children;
539	  for (const li of lis) li.classList.toggle('current', Number(li.dataset.i) === rp.cur);
540	  lis[rp.cur]?.scrollIntoView({ block: 'nearest' });
541	  $('rpCounter').textContent = `step ${rp.cur + 1} / ${rp.steps.length}`;
542	  $('rpPrev').disabled = rp.cur === 0;
543	  $('rpNext').disabled = rp.cur === rp.steps.length - 1;
544	}
545	
546	async function openReplay(d) {
547	  const req = ++rp.req;
548	  if ($('replay').hidden) rp.opener = document.activeElement;
549	  rp.steps = [];
550	  const q = new URLSearchParams({ fault: d.fault, seed: d.seed });
551	  if (d.run && d.ws) { q.set('run', d.run); q.set('ws', d.ws); }
552	  $('rpTitle').innerHTML = `Replay <code>${esc(d.fault)}</code> · seed ${esc(d.seed)}`;
553	  $('rpMeta').innerHTML = `<span class="badge">${d.ws ? 'patched code: ' + esc(d.ws) : 'original code'}</span><span class="badge">re-running this trial from its seed…</span>`;
554	  $('rpBroken').innerHTML = '';
555	  $('rpSteps').innerHTML = '';
556	  $('rpCounter').textContent = '';
557	  $('rpPrev').disabled = $('rpNext').disabled = true;
558	  $('replay').hidden = false;
559	  $('rpClose').focus();
560	  let r;
561	  try {
562	    const res = await fetch('/api/replay?' + q);
563	    r = await res.json();
564	    if (!res.ok) throw new Error(r.error || res.statusText);
565	  } catch (err) {
566	    if (req === rp.req) $('rpMeta').innerHTML = `<span class="bad">Replay failed: ${esc(err.message)}</span>`;
567	    return;
568	  }
569	  if (req !== rp.req) return;
570	  const o = r.observation;
571	  const refunds = o.refunds.map((x) => '$' + x.amount).join(' + ');
572	  $('rpMeta').innerHTML = [
573	    `<span class="badge"><span class="rp-out ${esc(o.outcome)}">${esc(OUTCOME_LABEL[o.outcome] ?? o.outcome)}</span></span>`,
574	    `<span class="badge">${esc(r.source)}</span>`,
575	    `<span class="badge">${Number(o.steps)} steps · ${Math.round(o.durationMs)}ms</span>`,
576	    `<span class="badge">faults fired: ${Number(o.faultsFired)}</span>`,
577	    `<span class="badge">refunds: ${refunds ? esc(refunds) : 'none'}</span>`,
578	  ].join('');
579	  $('rpBroken').innerHTML = r.broken.length
580	    ? r.broken.map((b) => `<li><b>✗ ${esc(b.rule)}</b> ${esc(b.detail ?? '')}<small>How it's checked: ${esc(b.how)}</small></li>`).join('')
581	    : '<li class="ok">✓ Every rule held</li>';
582	  rp.steps = r.timeline;
583	  $('rpSteps').innerHTML = r.timeline.map(stepView).join('');
584	  rpGo(0);
585	}
586	
587	function closeReplay() {
588	  if ($('replay').hidden) return;
589	  rp.req++;
590	  $('replay').hidden = true;
591	  rp.opener?.focus?.();
592	}
593	
594	function dotTarget(ev) {
595	  const dot = ev.target.closest?.('.dot[data-seed]');
596	  return dot ? { fault: dot.dataset.fault, seed: dot.dataset.seed, run: dot.dataset.run, ws: dot.dataset.ws } : null;
597	}
598	$('grid').addEventListener('click', (ev) => { const d = dotTarget(ev); if (d) openReplay(d); });
599	$('grid').addEventListener('keydown', (ev) => {
600	  if (ev.key !== 'Enter' && ev.key !== ' ') return;
601	  const d = dotTarget(ev);
602	  if (d) { ev.preventDefault(); openReplay(d); }
603	});
604	$('rpSteps').addEventListener('click', (ev) => { const li = ev.target.closest('.rp-step'); if (li) rpGo(Number(li.dataset.i)); });
605	$('rpPrev').addEventListener('click', () => rpGo(rp.cur - 1));
606	$('rpNext').addEventListener('click', () => rpGo(rp.cur + 1));
607	$('rpClose').addEventListener('click', closeReplay);
608	$('replay').addEventListener('click', (ev) => { if (ev.target === $('replay')) closeReplay(); });
609	document.addEventListener('keydown', (ev) => {
610	  if ($('replay').hidden) return;
611	  if (ev.key === 'Escape') closeReplay();
612	  else if (ev.key === 'ArrowLeft') { ev.preventDefault(); rpGo(rp.cur - 1); }
613	  else if (ev.key === 'ArrowRight') { ev.preventDefault(); rpGo(rp.cur + 1); }
614	});
615	
616	$('run').addEventListener('click', runChaos);
617	$('loopbtn').addEventListener('click', runLoopUI);
618	load();
619	</script>
