/* Bulwark design system: monochrome, editorial, precise.
   Ink on paper, Inter 300 for display, pill controls, generous whitespace.
   Colour carries meaning only: pass / broke a rule / crash / hang / runaway,
   and the resilience gradient. Shared by the landing page and the app. */
:root {
  --bg: #ffffff;
  --bg-2: #fafafa;
  --surface: #ffffff;
  --surface-muted: #f4f4f6;
  --surface-inverse: #0a0a0a;

  --fg: #0a0a0a;
  --fg-muted: rgba(10, 10, 10, 0.56);
  --fg-dim: rgba(10, 10, 10, 0.38);
  --fg-inverse: #ffffff;
  --fg-inverse-muted: rgba(255, 255, 255, 0.58);

  --line: rgba(0, 0, 0, 0.08);
  --line-strong: rgba(0, 0, 0, 0.12);
  --line-bold: rgba(0, 0, 0, 0.35);
  --line-inverse: rgba(255, 255, 255, 0.12);

  /* Meaning */
  --pass: #15803d;
  --pass-soft: rgba(21, 128, 61, 0.08);
  --broken: #b45309;
  --broken-soft: rgba(180, 83, 9, 0.08);
  --crash: #dc2626;
  --crash-soft: rgba(220, 38, 38, 0.08);
  --hung: #6d28d9;
  --runaway: #be185d;
  --pending: #e7e7ea;
  --resilience-grad: linear-gradient(90deg, #ef4444 0%, #f59e0b 45%, #10b981 100%);

  /* Agents: one quiet mark each */
  --red-agent: #dc2626;
  --blue-agent: #1d4ed8;
  --judge-agent: #0a0a0a;
  --guard: #0f766e;

  --radius-sm: 12px;
  --radius: 20px;
  --radius-lg: 28px;
  --pill: 999px;
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.04), 0 8px 24px -12px rgba(0, 0, 0, 0.12);
  --shadow-lg: 0 2px 4px rgba(0, 0, 0, 0.04), 0 24px 60px -24px rgba(0, 0, 0, 0.25);

  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);

  --font-sans: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-mono: 'Geist Mono', ui-monospace, SFMono-Regular, Menlo, monospace;

  color-scheme: light;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { max-width: 100vw; overflow-x: clip; }
html { scroll-behavior: smooth; }
body {
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font-sans);
  font-weight: 400;
  line-height: 1.5;
  letter-spacing: -0.005em;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
h1, h2, h3 { font-weight: 300; letter-spacing: -0.035em; line-height: 1.04; }
a { color: inherit; text-decoration: none; }
button { font: inherit; color: inherit; cursor: pointer; border: none; background: none; }
code, kbd, .mono { font-family: var(--font-mono); font-size: 0.92em; letter-spacing: 0; }
::selection { background: #0a0a0a; color: #fff; }
:focus-visible { outline: 2px solid #0a0a0a; outline-offset: 2px; border-radius: 6px; }

/* ---- Shared components ---- */

.wrap { width: 100%; max-width: 1240px; margin: 0 auto; padding: 0 24px; }
@media (max-width: 640px) { .wrap { padding: 0 16px; } }

/* Eyebrow: dot + small muted label */
.eyebrow { display: inline-flex; align-items: center; gap: 8px; font-size: 13px; color: var(--fg-muted); }
.eyebrow::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--fg); flex: none; }
.eyebrow.live::before { background: var(--pass); box-shadow: 0 0 0 4px var(--pass-soft); }
.inverse .eyebrow { color: var(--fg-inverse-muted); }
.inverse .eyebrow::before { background: var(--fg-inverse); }

/* Pills */
.pill {
  display: inline-flex; align-items: center; gap: 8px; height: 40px; padding: 0 18px;
  border-radius: var(--pill); border: 1px solid var(--line-strong); background: var(--surface);
  font-size: 14px; font-weight: 500; white-space: nowrap;
  transition: border-color .2s var(--ease-out), background .2s var(--ease-out), transform .2s var(--ease-out);
}
.pill:hover { border-color: var(--line-bold); }
.pill.sm { height: 32px; padding: 0 14px; font-size: 13px; }
.pill.muted { background: var(--surface-muted); border-color: transparent; color: var(--fg-muted); }
.pill.ink { background: var(--fg); color: var(--fg-inverse); border-color: var(--fg); }
.pill:disabled { opacity: .5; cursor: progress; }

/* Primary action: black pill with a white circular arrow */
.cta {
  display: inline-flex; align-items: center; gap: 14px; height: 52px; padding: 0 6px 0 24px;
  border-radius: var(--pill); background: var(--fg); color: var(--fg-inverse);
  font-size: 15px; font-weight: 500; white-space: nowrap;
  transition: transform .25s var(--ease-out), box-shadow .25s var(--ease-out);
}
.cta:hover { transform: translateY(-1px); box-shadow: var(--shadow-lg); }
.cta .arrow {
  width: 40px; height: 40px; border-radius: 50%; background: var(--fg-inverse); color: var(--fg);
  display: grid; place-items: center; transition: transform .3s var(--ease-spring);
}
.cta:hover .arrow { transform: rotate(45deg); }
.cta.sm { height: 44px; padding-left: 20px; gap: 12px; font-size: 14px; }
.cta.sm .arrow { width: 32px; height: 32px; }
.cta:disabled { opacity: .55; cursor: progress; transform: none; box-shadow: none; }

/* Cards */
.card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-lg); box-shadow: var(--shadow); }
.card.inverse { background: var(--surface-inverse); color: var(--fg-inverse); border-color: var(--surface-inverse); box-shadow: var(--shadow-lg); }

/* Top bar */
.topbar { position: sticky; top: 0; z-index: 30; background: rgba(255, 255, 255, 0.82); backdrop-filter: saturate(1.4) blur(14px); -webkit-backdrop-filter: saturate(1.4) blur(14px); }
.topbar .wrap { display: flex; align-items: center; justify-content: space-between; height: 76px; gap: 16px; }
.brand { display: inline-flex; align-items: center; gap: 10px; font-weight: 600; font-size: 18px; letter-spacing: -0.02em; }
.brand svg { flex: none; }
.topbar nav { display: flex; align-items: center; gap: 6px; }
.topbar nav a.link { padding: 8px 14px; border-radius: var(--pill); font-size: 14px; color: var(--fg-muted); transition: color .2s, background .2s; }
.topbar nav a.link:hover { color: var(--fg); background: var(--surface-muted); }

/* Segmented status switch (e.g. "Simulated · Claude via 0G") */
.segment { display: inline-flex; align-items: center; gap: 2px; padding: 3px; border-radius: var(--pill); background: var(--surface-muted); font-size: 13px; }
.segment span { padding: 6px 12px; border-radius: var(--pill); color: var(--fg-muted); display: inline-flex; align-items: center; gap: 6px; }
.segment span.on { background: var(--fg); color: var(--fg-inverse); }
.segment span .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; opacity: .6; }

/* Trial squares (shared vocabulary) */
.sq { width: 12px; height: 12px; border-radius: 3px; background: var(--pending); display: inline-block; }
.sq.pass { background: var(--pass); } .sq.broken { background: var(--broken); } .sq.crashed { background: var(--crash); }
.sq.hung { background: var(--hung); } .sq.runaway { background: var(--runaway); }

.legend { display: flex; flex-wrap: wrap; gap: 16px; font-size: 12.5px; color: var(--fg-muted); }
.legend span { display: inline-flex; align-items: center; gap: 7px; }

/* Agent tags */
.tag { display: inline-flex; align-items: center; height: 22px; padding: 0 8px; border-radius: 6px; font: 600 11px/1 var(--font-mono); letter-spacing: .04em; color: #fff; }
.tag.red { background: var(--red-agent); } .tag.blue { background: var(--blue-agent); } .tag.judge { background: var(--judge-agent); } .tag.guard { background: var(--guard); }

