import puppeteer from 'puppeteer-core';
const OUT = process.argv[2];
const BASE = 'http://localhost:5401/app';
const browser = await puppeteer.launch({ executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless: 'new', args: ['--no-sandbox'] });
const page = await browser.newPage();
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('requestfailed', (r) => errors.push('reqfailed: ' + r.url() + ' ' + r.failure()?.errorText));
const log = (...a) => console.log(...a);
const overflow = () => page.evaluate(() => ({ sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth }));

await page.setViewport({ width: 1440, height: 900, deviceScaleFactor: 2 });
await page.goto(BASE, { waitUntil: 'networkidle0' });
await page.waitForSelector('#grid .fcard');
await page.screenshot({ path: `${OUT}/app-desktop-idle.png` });
log('idle overflow', await overflow());

// Attack only
await page.click('#run');
await page.waitForFunction(() => !document.getElementById('run').disabled && document.querySelectorAll('.sq[data-seed]').length > 0, { timeout: 120000 });
log('attack squares', await page.evaluate(() => document.querySelectorAll('#grid .sq[data-seed]').length), await page.evaluate(() => [1,2,3,4].map((i) => document.getElementById('s' + i).textContent)));
await page.screenshot({ path: `${OUT}/app-attack-only.png`, fullPage: true });

// Replay from a failing square
await page.evaluate(() => document.querySelector('#grid .sq.broken[data-seed], #grid .sq.crashed[data-seed], #grid .sq[data-seed]').scrollIntoView({ block: 'center' }));
await page.click('#grid .sq.crashed[data-seed], #grid .sq.broken[data-seed], #grid .sq[data-seed]');
await page.waitForSelector('#rpSteps li', { timeout: 30000 });
await page.keyboard.press('ArrowRight');
await page.keyboard.press('ArrowRight');
log('replay counter', await page.$eval('#rpCounter', (e) => e.textContent), 'bad steps', await page.$$eval('.rp-step.rp-bad', (l) => l.length));
await page.screenshot({ path: `${OUT}/app-replay-desktop.png` });
await page.keyboard.press('Escape');
log('replay hidden after Esc', await page.$eval('#replay', (e) => e.hidden));

// Full loop
await page.click('#loopbtn');
await page.waitForFunction(() => getComputedStyle(document.getElementById('results')).display !== 'none', { timeout: 600000, polling: 1000 });
await new Promise((r) => setTimeout(r, 800));
log('loop stats', await page.evaluate(() => [1,2,3,4].map((i) => document.getElementById('s' + i).textContent)));
log('bigscore', await page.$eval('#bigscore', (e) => e.textContent), 'links', await page.$$eval('#links a', (l) => l.length), 'tl events', await page.$$eval('#timeline .ev', (l) => l.length));
log('findings', await page.$$eval('#findings li', (l) => l.length), 'prov', await page.$$eval('#findings .prov', (l) => l.map((x) => x.textContent.slice(0, 120))));
log('badge loaded', await page.$eval('#badge', (i) => i.complete && i.naturalWidth > 0));
await page.screenshot({ path: `${OUT}/app-loop-desktop.png`, fullPage: true });
await (await page.$('#loop')).screenshot({ path: `${OUT}/app-loop-section.png` });

// Replay a patched-code (after) square
const after = await page.$('#grid .dots.after .sq[data-ws]');
if (after) {
  await after.evaluate((e) => e.scrollIntoView({ block: 'center' }));
  await after.click();
  await page.waitForSelector('#rpSteps li', { timeout: 30000 });
  log('patched replay meta', await page.$eval('#rpMeta', (e) => e.textContent));
  await page.keyboard.press('Escape');
} else log('no after squares with ws');

// Newer optional events (server does not forward --slo/--tournament): feed synthetic events to the real handlers.
await page.evaluate(() => {
  const H = handlers; // eslint-disable-line
  H['slo-plan']({ type: 'slo-plan', confidence: 0.95, method: 'zero-failure (rule of three)', plans: [{ fault: 'timeout-after-commit', target: 0.99, confidence: 0.95, trials: 299, method: 'zero-failure' }] });
  H.verdict({ type: 'verdict', fault: 'timeout-after-commit', n: 1, status: 'fixed', reasons: ['all trials passed on fresh seeds'], pValue: 0.0001, afterPassed: 299, trials: 299, regressions: [], author: 'playbook',
    slo: { fault: 'timeout-after-commit', target: 0.99, confidence: 0.95, trials: 299, method: 'zero-failure', passed: 299, demonstrated: true, lowerBound: 0.99 },
    overhead: { scope: 'baseline', before: {}, after: {}, latencyP50Pct: 0.02, latencyP95Pct: 0.04, stepsDelta: 0.3, exceeded: [], withinBudget: true } });
  H.verdict({ type: 'verdict', fault: 'duplicate-webhook', n: 2, status: 'inconclusive', reasons: ['SLO not demonstrated'], pValue: 0.03, afterPassed: 296, trials: 299, regressions: [], author: 'claude-sonnet-5',
    slo: { fault: 'duplicate-webhook', target: 0.99, confidence: 0.95, trials: 299, method: 'zero-failure', passed: 296, demonstrated: false, lowerBound: 0.9724 },
    overhead: { scope: 'baseline', before: {}, after: {}, latencyP50Pct: 0.4, latencyP95Pct: null, stepsDelta: 1.2, exceeded: ['p95 latency +∞% > 20%'], withinBudget: false } });
  H.tournament({ type: 'tournament', fault: 'timeout-after-commit', round: 1, entrants: ['playbook', 'claude-sonnet-5', 'playbook-strong'], winner: 'playbook',
    ranking: [
      { rank: 1, entrant: 'playbook', status: 'fixed', sloDemonstrated: true, overhead: { latencyP95Pct: 0.04, withinBudget: true }, diffSize: 6, outcome: 'winner', reason: 'fixed, SLO demonstrated, smallest diff' },
      { rank: 2, entrant: 'claude-sonnet-5', status: 'fixed', sloDemonstrated: true, overhead: { latencyP95Pct: 0.12, withinBudget: true }, diffSize: 14, outcome: 'loser', reason: 'same tier, larger p95 overhead' },
      { rank: 3, entrant: 'playbook-strong', status: 'rejected', diffSize: 9, outcome: 'loser', reason: 'regressed duplicate-webhook' },
    ] });
});
await (await page.$('#timeline')).evaluate((e) => (e.scrollTop = e.scrollHeight));
await new Promise((r) => setTimeout(r, 300));
await (await page.$('#loop .loopgrid > .card')).screenshot({ path: `${OUT}/app-loop-events.png` });

// Phone width
await page.setViewport({ width: 390, height: 844, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
await new Promise((r) => setTimeout(r, 500));
log('mobile overflow', await overflow());
const wide = await page.evaluate(() => [...document.querySelectorAll('body *')].filter((e) => { const r = e.getBoundingClientRect(); return r.right > document.documentElement.clientWidth + 1 && r.width > 0 && !e.closest('.tablewrap, pre, #timeline'); }).map((e) => e.tagName + '.' + e.className).slice(0, 10));
log('elements past right edge', wide);
await page.evaluate(() => window.scrollTo(0, 0));
await page.screenshot({ path: `${OUT}/app-mobile-top.png` });
await page.screenshot({ path: `${OUT}/app-mobile-full.png`, fullPage: true });
await page.evaluate(() => document.querySelector('#grid .sq[data-seed]').scrollIntoView({ block: 'center' }));
await page.tap('#grid .sq.broken[data-seed], #grid .sq[data-seed]');
await page.waitForSelector('#rpSteps li', { timeout: 30000 });
await page.screenshot({ path: `${OUT}/app-replay-mobile.png` });
log('mobile overflow with modal', await overflow());

log('ERRORS', JSON.stringify(errors));
await browser.close();

